-- ============================================================================
-- v1349: Seed / sample data — Data Mapping fields (v1348) for the Data Migration demo project
-- ============================================================================
-- Companion seed to v1348 (rule 18.2). Fills the new Data Mapping fields on the 10 sample mapping
-- sheets of project SEED334-PRJ-08 (ids …-4000-a00f-…, fictional "Northbridge Bank" core banking
-- replacement; vendor-neutral, rule 26 — source column names are illustrative). Values already on a
-- record are kept; the seed only adds missing keys. Reviewer / owner pickers are left empty.
-- Prerequisites: v1348. Idempotent.
-- ============================================================================

UPDATE public.local_register_records r
SET field_values = v.vals::jsonb || COALESCE(r.field_values, '{}'::jsonb),
    updated_at = NOW()
FROM (VALUES
  ('00000000-0000-4000-a00f-000000000001', $j${"dms_reference":"DMS-CUS-01","data_object":"Customer","product_area":"customers_individual_and_corporate","mapping_version":"1.2","load_type":"static","load_sequence":10,"migration_wave":"Window 1 (static data), delta on the cutover weekend","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Customer master\nCustomer addresses\nCustomer relationships","extract_file_name":"NB_CUSTOMER_<YYYYMMDD>_<run>.txt","target_module":"Customer","target_table":"Customer master (bulk load)","load_method":"automated_load_mapping_sheet","record_key_rule":"New 8-digit customer number\nLegacy customer number kept as the alternate key\nDuplicates across instances merged; the record with the most complete KYC data is kept","field_mappings":"Customer number\tCUST_NO\tNew 8-digit number from the numbering table\tYes\t\nShort name\tCUST_SHORT_NAME\tTrim; upper case; max 35 characters\tYes\t\nSector\tSECTOR_CODE\tCode mapping (Sector table)\tYes\t1001\nIndustry\tINDUSTRY_CODE\tCode mapping (Industry table)\tYes\t\nNationality / residence\tNATIONALITY; RESIDENCE\tISO country code\tYes\t\nAccount officer\tRM_CODE\tMapped to the new officer IDs\tYes\tBranch default officer\nLegacy reference\tCUST_NO\tCopied unchanged (alternate key)\tYes\t","value_mappings":"Customer status\tA\tActive\nCustomer status\tD\tDeceased\nSector\tIND\t1001 Individual\nSector\tCORP\t2001 Corporate","mapping_completeness":100,"selection_criteria":"All active customers\nCustomers with at least one open account, contract, limit or collateral","exclusion_criteria":"Customers with no open products and no activity for 7 years (archived separately)","transformation_rules":"Special characters not allowed by the load tool removed at file level\nNames split into first, middle and last name for individuals","validation_rules":"Mandatory fields present\nCodes exist in the target reference tables\nNo duplicate alternate keys","data_quality_issues":"Address completeness 82% (target 85%)\nMissing industry and sector codes on older corporate customers","open_questions":"Customer short name rule for exceptions\tBusiness data owner\tOpen","expected_record_count":1400000,"load_results":"Mock 1\t2026-09-12\t1,400,000\t1,396,850\t3,150\tPassed with exceptions","reconciliation_keys":"Record count per instance and customer type\nSample of 200 customers checked field by field","reconciliation_report":"REC-M1-CUS-01","business_signoff_date":"2026-09-25","technical_signoff_date":"2026-09-22","change_history":"1.0\t2026-06-10\tMapping analyst\tFirst version\n1.2\t2026-09-24\tMapping analyst\tDuplicate merge rule after Mock 1"}$j$),
  ('00000000-0000-4000-a00f-000000000002', $j${"dms_reference":"DMS-ACC-01","data_object":"Customer account (takeover and balances)","product_area":"current_and_savings_accounts","mapping_version":"1.1","load_type":"financial","load_sequence":40,"migration_wave":"Window 2 (financial data)","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Accounts\nAccount balances and accruals\nPosting restrictions","extract_file_name":"NB_ACCOUNT_<YYYYMMDD>_<run>.txt","target_module":"Accounts","target_table":"Account takeover arrangement; capture balances","load_method":"automated_load_mapping_sheet","record_key_rule":"Instance 1 account numbers kept\nInstance 2 numbers become alternate keys; new 10-digit numbers issued","field_mappings":"Account number\tACCT_NO\tKept (Instance 1) or new 10-digit number (Instance 2)\tYes\t\nCustomer\tCUST_NO\tNew customer number via the customer cross-reference\tYes\t\nProduct\tCATEGORY\tCode mapping (product table)\tYes\t\nCurrency\tCCY\tISO currency code\tYes\t\nCurrent balance\tWORKING_BAL\tCapture balances step\tYes\t0\nAccrued credit interest\tACCR_CR_INT\tValue date = migration date\tNo\t0","value_mappings":"Product\t1001\tCurrent account – personal\nProduct\t6001\tSavings account – personal","mapping_completeness":95,"selection_criteria":"Customer account categories 1001–9999\nOpen accounts with or without balances","exclusion_criteria":"Closed accounts and accounts marked for closure with no balance","transformation_rules":"Savings accounts paying interest on the lowest balance: lowest balance migrated separately with the last accrual date","validation_rules":"Customer exists in the target\nProduct conditions set up in the target\nBalances total to the legacy trial balance per product and currency","open_questions":"Debit interest in arrears approach\tLending product owner\tOpen","expected_record_count":2150000,"load_results":"Mock 1\t2026-09-13\t2,150,000\t2,149,120\t880\tPassed with exceptions","reconciliation_keys":"Account count per product and currency\nBalance and accrued interest totals per product and currency","reconciliation_report":"REC-M1-ACC-01","business_signoff_date":"2026-10-02","change_history":"1.0\t2026-06-20\tMapping analyst\tFirst version\n1.1\t2026-09-30\tMapping analyst\tLowest-balance rule added"}$j$),
  ('00000000-0000-4000-a00f-000000000003', $j${"dms_reference":"DMS-DEP-01","data_object":"Deposit (takeover arrangement)","product_area":"term_fixed_deposits","mapping_version":"1.0","load_type":"financial","load_sequence":50,"migration_wave":"Window 2 (financial data)","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Money market – customer deposits","extract_file_name":"NB_DEPOSIT_<YYYYMMDD>_<run>.txt","target_module":"Deposits","target_table":"Deposit takeover arrangement","load_method":"automated_load_mapping_sheet","record_key_rule":"New deposit number; legacy deposit reference mapped as the alternate account ID and used in later loads","field_mappings":"Customer\tCUST_NO\tCustomer cross-reference\tYes\t\nProduct\tDEP_TYPE\tCode mapping (deposit products)\tYes\t\nAmount\tPRINCIPAL\tAs at the cut-off\tYes\t\nInterest rate\tINT_RATE\tOnly when different from the product\tNo\t\nAlternate ID\tDEAL_REF\tCopied unchanged\tYes\t","mapping_completeness":90,"selection_criteria":"All running fixed, call and notice deposits","exclusion_criteria":"Matured deposits (unless the maturity date is moved to the migration date)","validation_rules":"Settlement account exists\nMaturity date after the migration date","expected_record_count":185000,"reconciliation_keys":"Deposit count per product and tenor; principal total","change_history":"1.0\t2026-07-15\tMapping analyst\tFirst version"}$j$),
  ('00000000-0000-4000-a00f-000000000004', $j${"dms_reference":"DMS-DEP-02/03","data_object":"Deposit balances, principal adjustment and accruals","product_area":"term_fixed_deposits","mapping_version":"1.0","load_type":"financial","load_sequence":51,"migration_wave":"Window 2 (financial data)","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Money market – balances and accruals","extract_file_name":"NB_DEPOSIT_BAL_<YYYYMMDD>_<run>.txt","target_module":"Deposits","target_table":"Capture balances; adjust expected principal","load_method":"automated_load_mapping_sheet","record_key_rule":"Linked to the deposit through the legacy deposit reference (alternate ID)","field_mappings":"Arrangement\tDEAL_REF\tAlternate ID of the deposit\tYes\t\nPrincipal balance\tPRINCIPAL\tCapture balances\tYes\t\nExpected principal\tPRINCIPAL\tAdjust balance (already funded)\tYes\t\nAccrued interest\tACCR_INT\tValue date = migration date\tNo\t0","mapping_completeness":85,"transformation_rules":"Multi-value and sub-value fields documented per balance type","validation_rules":"Deposit loaded and authorised before this step","expected_record_count":185000,"reconciliation_keys":"Principal and accrued interest totals per product"}$j$),
  ('00000000-0000-4000-a00f-000000000005', $j${"dms_reference":"DMS-LND-01","data_object":"Loan (takeover arrangement)","product_area":"loans_and_lending_arrangements","mapping_version":"1.0","load_type":"financial","load_sequence":60,"migration_wave":"Window 2 (financial data)","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Loans\nRepayment schedules","extract_file_name":"NB_LOAN_<YYYYMMDD>_<run>.txt","target_module":"Lending","target_table":"Lending takeover arrangement","load_method":"automated_load_mapping_sheet","record_key_rule":"New loan number; legacy reference kept as the alternate key","field_mappings":"Customer\tCUST_NO\tCustomer cross-reference\tYes\t\nProduct\tLOAN_TYPE\tCode mapping (lending products)\tYes\t\nLimit\tLIMIT_REF\tLimit cross-reference\tYes\t\nCommitment amount\tSANCTION_AMT\tAs sanctioned\tYes\t\nRepayment frequency\tREPAY_FREQ\tSchedule regenerated from the frequency\tYes\tMonthly","mapping_completeness":80,"selection_criteria":"All running loans, including matured loans with overdue bills","validation_rules":"Limit and collateral loaded\nSettlement account exists","open_questions":"Interest-in-suspense exceptions file layout\tCredit operations\tOpen","expected_record_count":240000,"reconciliation_keys":"Loan count per product; commitment total"}$j$),
  ('00000000-0000-4000-a00f-000000000006', $j${"dms_reference":"DMS-LND-02/03/04","data_object":"Loan balances, commitment adjustment and bills","product_area":"loans_and_lending_arrangements","mapping_version":"0.9","load_type":"financial","load_sequence":61,"migration_wave":"Window 2 (financial data)","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Loan balances and accruals\nPast dues","extract_file_name":"NB_LOAN_BAL_<YYYYMMDD>_<run>.txt","target_module":"Lending","target_table":"Capture balances; adjust commitment; capture bills","load_method":"automated_load_mapping_sheet","record_key_rule":"Linked to the loan through the legacy loan reference (alternate ID)","field_mappings":"Current principal\tOUTSTANDING\tCapture balances\tYes\t\nOutstanding commitment\tUNDRAWN\tAdjust balance\tYes\t0\nOverdue principal\tPD_PRINCIPAL\tCapture bill with the original due date\tNo\t\nOverdue interest\tPD_INTEREST\tCapture bill with the original due date\tNo\t","mapping_completeness":70,"transformation_rules":"Ageing status taken from the legacy days past due","data_quality_issues":"Some past dues have no due date in Instance 2","expected_record_count":278000,"reconciliation_keys":"Principal, overdue and accrued totals; ageing buckets"}$j$),
  ('00000000-0000-4000-a00f-000000000007', $j${"dms_reference":"DMS-LIM-01","data_object":"Limit","product_area":"credit_limits_and_facilities","mapping_version":"1.1","load_type":"static","load_sequence":30,"migration_wave":"Window 2 (before accounts and loans)","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Limits","extract_file_name":"NB_LIMIT_<YYYYMMDD>_<run>.txt","target_module":"Limits","target_table":"Limit (bulk load)","load_method":"automated_load_mapping_sheet","record_key_rule":"New limit ID in the target format; legacy reference kept as the alternate key","field_mappings":"Limit ID\tLIMIT_REF\tNew format: customer.product.serial\tYes\t\nSanctioned amount\tSANCTION_AMT\tOriginal sanctioned amount\tYes\t\nExpiry date\tEXPIRY_DATE\tExpired: migration date + 1 day, original kept in a local field\tYes\t","mapping_completeness":100,"transformation_rules":"Global limits created for multi-purpose credit lines","expected_record_count":96000,"load_results":"Mock 1\t2026-09-13\t96,000\t96,000\t0\tPassed","reconciliation_keys":"Limit count and sanctioned totals","business_signoff_date":"2026-09-28","technical_signoff_date":"2026-09-26"}$j$),
  ('00000000-0000-4000-a00f-000000000008', $j${"dms_reference":"DMS-COL-01/02","data_object":"Collateral right and collateral","product_area":"collateral_and_collateral_rights","mapping_version":"1.0","load_type":"static","load_sequence":20,"migration_wave":"Window 1 (static data)","source_system":"Legacy core banking – Instance 1 (retail and SME); Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Collateral","extract_file_name":"NB_COLLATERAL_<YYYYMMDD>_<run>.txt","target_module":"Collateral","target_table":"Collateral right; collateral","load_method":"automated_load_mapping_sheet","record_key_rule":"Collateral right ID = customer number.serial\nCollateral ID = customer number.serial.serial","field_mappings":"Collateral right ID\tCUST_NO + SEQ\tcustomer.serial\tYes\t\nCollateral type\tCOLL_TYPE\tCode mapping (collateral types)\tYes\t\nValue\tMARKET_VALUE\tLatest valuation\tYes\t\nLimit reference\tLIMIT_REF\tLimit cross-reference\tYes\t","mapping_completeness":100,"validation_rules":"Collateral rights loaded before collateral items","expected_record_count":71000,"load_results":"Mock 1\t2026-09-12\t71,000\t70,940\t60\tPassed with exceptions","reconciliation_keys":"Count and total value per collateral type","business_signoff_date":"2026-09-29"}$j$),
  ('00000000-0000-4000-a00f-000000000009', $j${"dms_reference":"DMS-TF-01 to 04","data_object":"Letters of credit, drawings, guarantees and bills","product_area":"letters_of_credit_issued_and_advised","mapping_version":"0.8","load_type":"financial","load_sequence":70,"migration_wave":"Window 2 (financial data)","source_system":"Legacy core banking – Instance 2 (corporate and treasury)","source_tables":"Letters of credit\nDrawings\nGuarantees\nBills","extract_file_name":"NB_TRADE_<YYYYMMDD>_<run>.txt","target_module":"Trade finance","target_table":"Letters of credit; drawings; guarantees; bills","load_method":"automated_load_mapping_sheet","record_key_rule":"Legacy LC number kept in the old LC number field; parent LCs loaded before transferred LCs","field_mappings":"LC amount\tLC_OUTSTANDING\tNet outstanding amount\tYes\t\nOriginal amount\tLC_AMOUNT\tLocal field when different\tNo\t\nPayment method (drawing)\t—\tInternal account\tYes\tInternal account","mapping_completeness":60,"data_quality_issues":"Expired LCs with liability need a liability reversal date","open_questions":"Treatment of usance LCs with accepted documents\tTrade finance operations\tOpen","expected_record_count":7300}$j$),
  ('00000000-0000-4000-a00f-00000000000a', $j${"dms_reference":"DMS-GL-01","data_object":"General ledger balances (journal capture)","product_area":"general_ledger_pandl_and_customer_balances","mapping_version":"1.0","load_type":"financial","load_sequence":35,"migration_wave":"Window 2 (first financial load)","source_system":"Finance and general ledger system (legacy trial balance)","source_tables":"Trial balance by GL line, currency and company","extract_file_name":"NB_GL_BAL_<YYYYMMDD>_<run>.xlsx","target_module":"General ledger","target_table":"Journal capture (balanced)","load_method":"journal_capture","record_key_rule":"One journal per product takeover account, currency and company","field_mappings":"Takeover account\tGL_LINE\tGL line to takeover account mapping\tYes\t\nAmount\tBALANCE\tSigned balance from the trial balance\tYes\t\nCurrency\tCCY\tISO currency code\tYes\t","mapping_completeness":100,"validation_rules":"Journal balances to zero\nLegacy general ledger balanced before the migration date","reconciliation_keys":"Trial balance comparison by GL line and currency\nTakeover accounts at zero after all loads","notes":"Unexplained differences go to the take-on differences account and are signed off as known differences"}$j$)
) AS v(id, vals)
WHERE r.id = v.id::uuid AND r.is_deleted = FALSE;

-- Check: how many sample mapping sheets now carry the new fields.
SELECT count(*) FILTER (WHERE field_values ? 'dms_reference') AS with_dms_reference, count(*) AS sample_records
FROM public.local_register_records
WHERE register_id = '00000000-0000-4000-9001-00000000000f'::uuid AND id::text LIKE '00000000-0000-4000-a00f-%';
